 void ShowFittedInformationK(){var ship=FittingWorld.Player;bool simulated=fittingSimulation!=null;string key="tactical/fitted/"+Guid.NewGuid().ToString("N");var entry=new InformationEntry{Key=key,Id=ship.InstanceId,Name=ship.HullName+(simulated?" / simulated fit":" / fitted ship"),Kind="Fitted ship",Group="Fitting / Snapshot",Description=simulated?"Isolated simulation snapshot. Reopen to refresh after changing the simulated fit.":"Fitted ship attribute snapshot. Reopen to refresh."};entry.Add("Description",entry.Description);entry.Add("Source","Hull type ID",UnifiedCatalog40.SourceId(ship.CombatHull).ToString());entry.Add("Source","Profile",simulated?"Simulation / inventory and wallet isolated":"Live player ship");foreach(var a in ship.Attributes.Where(a=>a.Value.HasValue)){string label=ShipAttributeCatalog.ByKey.GetValueOrDefault(a.Key)?.Label??a.Key,value=InfoValue(a.Key,ship.Stat(a.Key));entry.Add("Attributes",label,value);entry.Stats[label]=value;}foreach(var m in FittingLayoutModel.Installed(ship))entry.Add("Equipment",m.Name,$"{m.Bank} / {(m.Burnt?"burnt":m.Online==false?"offline":m.Active?"active":"online")}",InformationCatalog.ItemKey(m.Id));informationSnapshots[key]=entry;ShowInformation(key,true);}
 void DrawComparisonK(DesktopWindow w){if(w.CompareKeysK.Count==0)w.CompareKeysK=informationCompare.ToList();var all=w.CompareKeysK.Select(ResolveInformation).OfType<InformationEntry>().ToArray();int pages=Math.Max(1,(all.Length+3)/4);w.TabK=Math.Clamp(w.TabK,0,pages-1);var entries=all.Skip(w.TabK*4).Take(4).ToArray();var r=w.Bounds;int x=r.X+12,y=r.Y+39,width=r.Width-24;ui.Button(new(x,y,170,25),w.CompareDiffK?"Differences only":"All attributes",()=>{w.CompareDiffK=!w.CompareDiffK;infoDifferences=w.CompareDiffK;SaveDesktop();},"Compare differences",w.CompareDiffK);ui.Button(new(x+180,y,185,25),"Pin: "+ShortInfo(w.CompareStatK,18),()=>ShowPopup("Comparison attribute",all.SelectMany(e=>e.Stats.Keys).Distinct().Order().Select(k=>(k,(Action)(()=>{w.CompareStatK=k;SaveDesktop();})))),"Compare sort");ui.Button(new(x+375,y,150,25),$"Items {w.TabK+1}/{pages}",()=>{w.TabK=(w.TabK+1)%pages;SaveDesktop();});ui.Button(new(x+535,y,130,25),"Remove item",()=>ShowPopup("Remove from comparison",all.Select(e=>(e.Name,(Action)(()=>{w.CompareKeysK.Remove(e.Key);informationCompare.Remove(e.Key);SaveDesktop();})))));y+=35;int labelWidth=Math.Min(240,width/3),cw=Math.Max(50,(width-labelWidth)/Math.Max(1,entries.Length));for(int i=0;i<entries.Length;i++){var e=entries[i];ui.Button(new(x+labelWidth+i*cw,y,cw-3,28),ShortInfo(e.Name,Math.Max(6,cw/7)),()=>ShowInformation(e.Key,true),"Compare item / "+e.Key);ui.Text("Type "+(e.MarketId.Length>0?UnifiedCatalog40.SourceId(e.MarketId).ToString():e.Id),x+labelWidth+i*cw+4,y+33,Muted,10);}y+=54;var attributes=all.SelectMany(e=>e.Stats.Keys).Distinct().Where(k=>!w.CompareDiffK||all.Select(e=>e.Stats.GetValueOrDefault(k,"—")).Distinct().Count()>1).OrderBy(k=>k==w.CompareStatK?0:1).ThenBy(k=>k).ToArray();int cap=Math.Max(1,(r.Bottom-75-y)/26);w.InfoScroll=Math.Clamp(w.InfoScroll,0,Math.Max(0,attributes.Length-cap));foreach(var key in attributes.Skip(w.InfoScroll).Take(cap)){ui.Text(ShortInfo(key,labelWidth/7),x+4,y+6,Muted,11);for(int i=0;i<entries.Length;i++)ui.Text(ShortInfo(entries[i].Stats.GetValueOrDefault(key,"—"),Math.Max(5,cw/7)),x+labelWidth+i*cw,y+6,White,11);ui.Line(new(x,y+25),new(r.Right-12,y+25),new Color(30,41,48));y+=26;}ui.Text($"{all.Length}/10 comparison items / {attributes.Length} attributes / wheel to scroll",x,r.Bottom-45,Cyan,11);ui.Text("Values retain their source units. Add through an Information window's options.",x,r.Bottom-25,Muted,11);}
